mapper.select:
select
mn.* from Audit_Settlement mn
where mn.con_id=#{conId}

select
c1.C_Name as cName, c2.C_Name as asAuditUnitName, c1.C_Name_History as cNameHistory, c1.C_Abbreviation as cAbbName, sec.Sec_Name as secName, sec.Sec_Code as secCode, con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, mn.* from Audit_Settlement mn
left join Sys_Company c1 on c1.C_Id=mn.As_Create_Cid left join Sys_Company c2 on c2.C_Id=mn.As_Audit_Unit left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join Con_Contract con on con.Con_Id=mn.Con_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.As_Create_Time DESC
